"""Regenerates src/WcpExtensions/Slots.g.cs (fixed command classes behind toolkit buttons).
Usage: python tools/gen-slots.py [count]   (default 256; keep SlotTable.Count in sync automatically)"""
import os, sys

count = int(sys.argv[1]) if len(sys.argv) > 1 else 256
here = os.path.dirname(os.path.abspath(__file__))
out = os.path.join(here, "..", "src", "WcpExtensions", "Slots.g.cs")
lines = [
    "// <auto-generated> Fixed command classes behind toolkit buttons. Regenerate with tools/gen-slots.py. </auto-generated>",
    "using Autodesk.Revit.Attributes;",
    "using Autodesk.Revit.DB;",
    "using Autodesk.Revit.UI;",
    "",
    "namespace WcpExtensions.Slots",
    "{",
    "    static class SlotTable",
    "    {",
    f"        public const int Count = {count};",
    "",
    "        public static string ClassName(int slot) => \"WcpExtensions.Slots.S\" + slot.ToString(\"000\");",
    "    }",
    "",
    "    /// <summary>Runs whatever toolkit command is bound to this slot right now.</summary>",
    "    public abstract class SlotCommand : IExternalCommand",
    "    {",
    "        protected abstract int Slot { get; }",
    "",
    "        public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements) =>",
    "            ToolkitHost.RunSlot(Slot, commandData, ref message, elements);",
    "    }",
    "",
]
for i in range(count):
    lines.append(f"    [Transaction(TransactionMode.Manual)] public sealed class S{i:03d} : SlotCommand {{ protected override int Slot => {i}; }}")
lines.append("}")
with open(out, "w", newline="") as f:
    f.write("\r\n".join(lines) + "\r\n")
print("wrote", out, count, "slots")
